function normalizeCodexEvent(item, lifecycleStatus, rootPath) {
    if (!item || typeof item.id !== 'string' || typeof item.type !== 'string') return null;
    const type = canonicalCodexItemType(item.type);
    if (!SUPPORTED_CODEX_ITEM_TYPES.has(type)) return null;
    const normalizedItem = type === item.type ? item : { ...item, type };
    if (type === 'reasoning') return reasoningEvent(normalizedItem, lifecycleStatus);
    if (type === 'commandExecution') return commandEvent(normalizedItem, lifecycleStatus);
    if (type === 'fileChange') return fileEvent(normalizedItem, lifecycleStatus, rootPath);
    if (type === 'mcpToolCall') return mcpEvent(normalizedItem, lifecycleStatus);
    if (type === 'dynamicToolCall') return dynamicToolEvent(normalizedItem, lifecycleStatus);
    if (type === 'collabAgentToolCall') return collaborationEvent(normalizedItem, lifecycleStatus);
    if (type === 'webSearch') {
        return {
            ...eventBase(normalizedItem, lifecycleStatus, 'Web search'),
            content: normalizedItem.query,
            output: boundedAgentResult(normalizedContent(normalizedItem.action) ?? ''),
        };
    }
    if (type === 'imageView') {
        return { ...eventBase(normalizedItem, lifecycleStatus, 'Image view'), content: normalizedItem.path };
    }
    if (type === 'plan') {
        return { ...eventBase(normalizedItem, lifecycleStatus, 'Plan'), content: normalizedItem.text };
    }
    if (type === 'contextCompaction') {
        return { ...eventBase(normalizedItem, lifecycleStatus, 'Context compacted') };
    }
    if (type === 'enteredReviewMode' || type === 'exitedReviewMode') {
        const label = type === 'enteredReviewMode' ? 'Entered review mode' : 'Exited review mode';

        return { ...eventBase(normalizedItem, lifecycleStatus, label), content: normalizedItem.review };
    }

    return null;
}

function diagnosticEvent(method, itemType, itemId, sequence) {
    const providerItemId = typeof itemId === 'string' && itemId.length > 0 ? itemId : 'unknown';
    const normalizedType = typeof itemType === 'string' && itemType.length > 0 ? itemType : 'unknown';

    return {
        content: `${method}: ${normalizedType} (${providerItemId})`,
        label: 'Codex protocol diagnostic',
        providerItemId: `diagnostic:${providerItemId}:${sequence}`,
        status: 'completed',
        type: 'diagnostic',
    };
}

function systemEvent(method, params) {
    const turnId = typeof params.turnId === 'string' ? params.turnId : 'unknown-turn';
    const providerItemId = `system:${turnId}:${method}`;
    if (method === 'model/rerouted') {
        return {
            content: `${params.fromModel} to ${params.toModel}: ${optionalContent(params.reason)}`,
            label: 'Model rerouted',
            providerItemId,
            status: 'completed',
            type: 'system',
        };
    }
    if (method === 'model/safetyBuffering/updated') {
        return {
            content: optionalContent({ reasons: params.reasons, useCases: params.useCases }),
            label: 'Safety buffering',
            providerItemId,
            status: params.showBufferingUi ? 'inProgress' : 'completed',
            type: 'system',
        };
    }
    if (method === 'model/verification') {
        return {
            content: optionalContent(params.verifications),
            label: 'Model verification',
            providerItemId,
            status: 'completed',
            type: 'system',
        };
    }

    return null;
}

module.exports = {
    countUnifiedDiffLines,
    diagnosticEvent,
    normalizeCodexEvent,
    systemEvent,
};

const {
    activityConversationReference,
    loadActivityValue,
    queueActivityUpdate,
    resolveActivityPath,
    upsertConversation,
    upsertActivityConversation,
    writeActivityFile,
} = require('../activity/activity_files');
const { appendCardActivityReference } = require('../activity/card_activity_reference');
const { assertGitRoot, commitTrackedPaths, requireRootPath } = require('../../git/git_commands');
const { persistConversationAndProjectUsage } = require('./project_agent_token_usage');

function requireActivityRequest(request) {
    if (!request?.activityProject) throw new Error('Missing agent activityProject');
    if (!request.activityOrigin) throw new Error('Missing agent activityOrigin');
    if (typeof request.projectFolder !== 'string') throw new Error('Missing agent projectFolder');

    return request;
}

function conversationReference(request, conversationId) {
    const activityRequest = requireActivityRequest(request);

    return activityConversationReference(activityRequest.projectFolder, activityRequest.activityOrigin, conversationId);
}

async function persistTerminalConversation(run) {
    requireActivityRequest(run.request);
    await persistConversationAndProjectUsage(run);
}

async function persistInitialCardConversation(run, dependencyOverrides = {}) {
    const request = requireActivityRequest(run.request);
    if (request.activityOrigin.kind !== 'card') throw new Error('Initial card conversation requires card activity origin');
    if (typeof request.cardPath !== 'string' || request.cardPath.length === 0) throw new Error('Missing agent cardPath');
    const rootPath = requireRootPath(request.activityProject);
    const assertRepositoryRoot = dependencyOverrides.assertGitRoot ?? assertGitRoot;
    await assertRepositoryRoot(rootPath);
    const { absolutePath, relativePath } = resolveActivityPath(rootPath, request.projectFolder, request.activityOrigin);
    const appendReference = dependencyOverrides.appendCardActivityReference ?? appendCardActivityReference;
    const commitPaths = dependencyOverrides.commitTrackedPaths ?? commitTrackedPaths;

    return queueActivityUpdate(absolutePath, async () => {
        const activity = upsertConversation(
            await loadActivityValue(absolutePath, request.activityOrigin),
            run.conversation,
        );
        await writeActivityFile(absolutePath, activity);
        await appendReference(
            request.activityProject,
            request.cardPath,
            request.activityOrigin.cardInternalId,
            relativePath,
        );
        await commitPaths(rootPath, [relativePath, request.cardPath], 'Start card agent activity');

        return { activity, relativePath };
    });
}

async function persistConversationCheckpoint(run, dependencyOverrides = {}) {
    const request = requireActivityRequest(run.request);
    const persistInitial = dependencyOverrides.persistInitialCardConversation ?? persistInitialCardConversation;
    const upsertConversationCheckpoint = dependencyOverrides.upsertActivityConversation ?? upsertActivityConversation;
    if (request.activityOrigin.kind === 'card' && !request.conversation) {
        await persistInitial(run);
        return;
    }
    await upsertConversationCheckpoint(
        request.activityProject,
        request.projectFolder,
        request.activityOrigin,
        run.conversation,
    );
}

module.exports = {
    conversationReference,
    persistConversation: persistTerminalConversation,
    persistConversationCheckpoint,
    persistInitialCardConversation,
    persistTerminalConversation,
};

import TerminalOutlined from '@mui/icons-material/TerminalOutlined'
import { Box, Button, Stack, Typography } from '@mui/material'
import { useState } from 'react'
import type { AgentConversationEvent } from '../../../../data/data_types'
import { commandPreview, eventHasError, eventStatusLabel } from './event_display'

const COMMAND_DETAIL_MAX_HEIGHT = 320

interface CommandExecutionEventProps {
    event: AgentConversationEvent
    grouped: boolean
}

function detailValue(value: string | number) {
    return (
        <Box
            component="pre"
            sx={{
                fontFamily: 'monospace',
                m: 0,
                overflowWrap: 'anywhere',
                whiteSpace: 'pre-wrap',
                wordBreak: 'break-word',
            }}
        >
            {value}
        </Box>
    )
}

/** Collapsed command lifecycle entry with exact execution detail on demand. */
export function CommandExecutionEvent({ event, grouped }: CommandExecutionEventProps) {
    const [expanded, setExpanded] = useState(false)
    const preview = commandPreview(event.command) || 'Command'
    const hasError = eventHasError(event.status)
    const durationMs = typeof event.durationMs === 'number' && Number.isFinite(event.durationMs)
        ? event.durationMs
        : null
    const exitCode = typeof event.exitCode === 'number' && Number.isSafeInteger(event.exitCode)
        ? event.exitCode
        : null
    const toggleExpanded = () => {
        setExpanded((current) => !current)
    }

    return (
        <Box
            sx={{
                border: grouped ? 'none' : '1px solid',
                borderColor: hasError ? 'error.main' : 'divider',
                borderRadius: grouped ? 0 : 1,
                flexShrink: 0,
                minWidth: 0,
                overflow: 'hidden',
            }}
        >
            <Button
                aria-expanded={expanded}
                aria-label={`Command details: ${preview}`}
                fullWidth
                onClick={toggleExpanded}
                startIcon={<TerminalOutlined />}
                sx={{
                    color: hasError ? 'error.main' : 'text.secondary',
                    display: 'flex',
                    justifyContent: 'flex-start',
                    minWidth: 0,
                    px: 1,
                    py: 0.75,
                    textAlign: 'left',
                }}
            >
                <Stack direction="row" spacing={1} sx={{ alignItems: 'center', minWidth: 0, width: '100%' }}>
                    <Typography noWrap sx={{ flex: 1, minWidth: 0 }} variant="caption">{preview}</Typography>
                    <Typography color="inherit" role="status" variant="caption">
                        {eventStatusLabel(event.status)}
                    </Typography>
                </Stack>
            </Button>
            {expanded ? (
                <Stack
                    spacing={1}
                    sx={{
                        bgcolor: 'background.default',
                        borderTop: '1px solid',
                        borderColor: 'divider',
                        color: hasError ? 'error.main' : 'text.secondary',
                        maxHeight: COMMAND_DETAIL_MAX_HEIGHT,
                        minWidth: 0,
                        overflow: 'auto',
                        p: 1,
                    }}
                >
                    <Box><Typography color="custom.text3" variant="caption">Command</Typography>{detailValue(event.command ?? '')}</Box>
                    {event.workingDirectory ? (
                        <Box><Typography color="custom.text3" variant="caption">Working directory</Typography>{detailValue(event.workingDirectory)}</Box>
                    ) : null}
                    {event.content ? (
                        <Box><Typography color="custom.text3" variant="caption">Output</Typography>{detailValue(event.content)}</Box>
                    ) : null}
                    {exitCode !== null || durationMs !== null ? (
                        <Stack direction="row" spacing={2}>
                            {exitCode !== null ? (
                                <Typography variant="caption">Exit code: {exitCode}</Typography>
                            ) : null}
                            {durationMs !== null ? (
                                <Typography variant="caption">Duration: {durationMs} ms</Typography>
                            ) : null}
                        </Stack>
                    ) : null}
                </Stack>
            ) : null}
        </Box>
    )
}
